SELECT tblEingabeUnElement.Elektrolyseur, tblEingabeUnElement.Position, tblEingabeUnElement.Datum, tblEingabeUnElement.Zeit, tblEingabeUnElement.[I Gesamt], [I Gesamt]/GetGewFlaeche() AS i, tblEingabeUnElement.Cc, tblEingabeUnElement.[t An], tblEingabeUnElement.[t Ka], ([t An]+[t Ka])/2 AS tm, [tblEingabeUnElement]![U] AS Um, UnBer([Um],[i],[tm],[Cc]) AS Un, GetGewiRef() AS iRef, GetGewtKorrektur() AS tKorr, GetGewcKorrektur() AS cKorr
FROM tblElektrolyseurbezeichnung, tblGewDaten, tblEingabeUnElement
WHERE (((tblEingabeUnElement.Elektrolyseur)=(SELECT Bezeichnung FROM tblElektrolyseurbezeichnung WHERE tblGewDaten.IDElektrolyseurUnCeSpcElement = tblElektrolyseurbezeichnung.Nr)) AND ((tblEingabeUnElement.Position)=(SELECT IDPositionUnCeSpcElement FROM tblGewDaten)) AND ((tblEingabeUnElement.Datum)>[tblGewDaten].[Anfangsdatum] And (tblEingabeUnElement.Datum)<[tblGewDaten].[Enddatum]) AND ((tblEingabeUnElement.[I Gesamt]) Is Not Null) AND ((tblEingabeUnElement.Cc) Is Not Null) AND ((tblEingabeUnElement.[t An]) Is Not Null) AND ((tblEingabeUnElement.[t Ka]) Is Not Null));
